export default{cssContent:"/*\n * Copyright (c) 2015 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n.resources-dividers {\n  position: absolute;\n  left: 0;\n  right: 0;\n  top: 0;\n  z-index: -100;\n  bottom: 0;\n}\n\n.resources-event-dividers {\n  position: absolute;\n  left: 0;\n  right: 0;\n  height: 100%;\n  top: 0;\n  z-index: 300;\n  pointer-events: none;\n}\n\n.resources-dividers-label-bar {\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  background-clip: padding-box;\n  height: 20px;\n  z-index: 200;\n  pointer-events: none;\n  overflow: hidden;\n}\n\n.resources-divider {\n  position: absolute;\n  width: 1px;\n  top: 0;\n  bottom: 0;\n  background-color: var(--sys-color-divider);\n}\n\n.resources-event-divider {\n  position: absolute;\n  width: 1px;\n  top: 0;\n  bottom: 0;\n  z-index: 300;\n}\n\n.resources-divider-label {\n  position: absolute;\n  top: 4px;\n  right: 3px;\n  font-size: 80%;\n  white-space: nowrap;\n  pointer-events: none;\n}\n\n.timeline-grid-header {\n  height: 20px;\n  pointer-events: none;\n}\n"};